using Microsoft.UI.Xaml.Media;
using Microsoft.UI.Xaml.Media.Imaging;
using Windows.Storage.Streams;

namespace Schoology.WinUI;

internal static class FolderIcons
{
    // These are the exact folder PNGs embedded by Tauri port.28. Keeping them
    // in the renderer avoids fragile runtime asset paths and preserves the
    // Schoology folder artwork in both light and dark themes.
    private static readonly Dictionary<string, string> EncodedIcons = new(StringComparer.OrdinalIgnoreCase)
    {
        ["black"] = "",
        ["blue"] = "",
        ["gray"] = "",
        ["green"] = "",
        ["orange"] = "",
        ["pink"] = "",
        ["purple"] = "",
        ["red"] = "",
        ["yellow"] = ""
    };
    private static readonly Dictionary<string, BitmapImage> Cache = new(StringComparer.OrdinalIgnoreCase);

    public static async Task<ImageSource> LoadAsync(string? color)
    {
        var key = color?.Trim().ToLowerInvariant() ?? "gray";
        if (!EncodedIcons.ContainsKey(key)) key = "gray";
        if (Cache.TryGetValue(key, out var cached)) return cached;

        var bytes = Convert.FromBase64String(EncodedIcons[key]);
        using var stream = new InMemoryRandomAccessStream();
        using var writer = new DataWriter(stream);
        writer.WriteBytes(bytes);
        await writer.StoreAsync();
        stream.Seek(0);

        var image = new BitmapImage();
        await image.SetSourceAsync(stream);
        Cache[key] = image;
        return image;
    }
}
